    var b = 0;

    $(".collapse").on("click", function() {
        var th = $(this);
        var cur_item = $(this).data('collapse');

        var show = th.children().data('show');
        var hide = th.children().data('hide');

        if(show == undefined || hide == undefined){
            show = th.data('show');
            hide = th.data('hide');
        }
        
        
        var c = $(this).prev();
        var e = $("." + cur_item).height() + 100;

        th.toggleClass('is_active');

        if(th.hasClass('is_active')){
            // открытие
            th.parent().addClass("open");

            th.children('span').text(hide);

            $(c).animate({
                height: e
            }, 1e3, function() {});
        }else{
            // закрытие
            $(".tabs-container .tabs-item").removeClass("open");
            th.parent().removeClass("open");
            th.removeClass("active");

            th.children('span').text(show);

            $(c).animate({
                height: 467
            }, 1e3, function() {});
        }
    });
